    58	    const menuItems = useMemo(() => {
    59	        const baseMenuItems: MenuItem[] = [
    60	            {
    61	                translationKey: 'initialSettingsPage.aboutPage.appDownloadLinks',
    62	                icon: Expensicons.Link,
    63	                action: waitForNavigate(() => Navigation.navigate(ROUTES.SETTINGS_APP_DOWNLOAD_LINKS)),
    64	            },
    65	            {
    66	                translationKey: 'initialSettingsPage.aboutPage.viewKeyboardShortcuts',
    67	                icon: Expensicons.Keyboard,
    68	                action: waitForNavigate(() => Navigation.navigate(ROUTES.KEYBOARD_SHORTCUTS)),
    69	            },
    70	            {
    71	                translationKey: 'initialSettingsPage.aboutPage.viewTheCode',
    72	                icon: Expensicons.Eye,
    73	                iconRight: Expensicons.NewWindow,
    74	                action: () => {
    75	                    Link.openExternalLink(CONST.GITHUB_URL);
    76	                    return Promise.resolve();
    77	                },
    78	                link: CONST.GITHUB_URL,
    79	            },
    80	            {
    81	                translationKey: 'initialSettingsPage.aboutPage.viewOpenJobs',
    82	                icon: Expensicons.MoneyBag,
    83	                iconRight: Expensicons.NewWindow,
    84	                action: () => {
