    89	            },
    90	            {
    91	                translationKey: 'initialSettingsPage.aboutPage.reportABug',
    92	                icon: Expensicons.Bug,
    93	                action: waitForNavigate(Report.navigateToConciergeChat),
    94	            },
    95	        ];
    96	
    97	        return baseMenuItems.map(({translationKey, icon, iconRight, action, link}: MenuItem) => ({
    98	            key: translationKey,
    99	            title: translate(translationKey),
   100	            icon,
   101	            iconRight,
   102	            onPress: action,
   103	            shouldShowRightIcon: true,
   104	            onSecondaryInteraction: link
   105	                ? (event: GestureResponderEvent | MouseEvent) => ReportActionContextMenu.showContextMenu(CONST.CONTEXT_MENU_TYPES.LINK, event, link, popoverAnchor.current)
   106	                : undefined,
   107	            ref: popoverAnchor,
   108	            shouldBlockSelection: !!link,
   109	            wrapperStyle: [styles.sectionMenuItemTopDescription],
   110	        }));
   111	    }, [styles, translate, waitForNavigate]);
   112	
   113	    const overlayContent = useCallback(
   114	        () => (
   115	            <View style={[styles.pAbsolute, styles.w100, styles.h100, styles.justifyContentEnd, styles.pb3]}>
