   125	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   126	        [],
   127	    );
   128	
   129	    return (
   130	        <ScreenWrapper
   131	            shouldEnablePickerAvoiding={false}
   132	            shouldShowOfflineIndicatorInWideScreen
