   137	                shouldShowBackButton={shouldUseNarrowLayout}
   138	                shouldDisplaySearchRouter
   139	                onBackButtonPress={() => Navigation.goBack(ROUTES.SETTINGS)}
   140	                icon={Illustrations.PalmTree}
   141	            />
   142	            <ScrollView contentContainerStyle={styles.pt3}>
