   167	                        <TextLink
   168	                            style={[styles.textMicroSupporting, styles.link]}
   169	                            href={CONST.TERMS_URL}
   170	                        >
   171	                            {translate('initialSettingsPage.readTheTermsAndPrivacy.phrase2')}
   172	                        </TextLink>{' '}
   173	                        {translate('initialSettingsPage.readTheTermsAndPrivacy.phrase3')}{' '}
   174	                        <TextLink
   175	                            style={[styles.textMicroSupporting, styles.link]}
   176	                            href={CONST.PRIVACY_URL}
   177	                        >
   178	                            {translate('initialSettingsPage.readTheTermsAndPrivacy.phrase4')}
   179	                        </TextLink>
   180	                        .
   181	                    </Text>
   182	                </View>
   183	            </ScrollView>
